-- ============================================================
-- Fix: lessons.content keyed by FOLDED lesson title (pure ASCII)
-- ============================================================
-- The builder folded every em/en dash (U+2014/U+2013) in the
-- on-disk titles down to a plain hyphen and lowercased them.
-- The matches on the LIVE side normalize the same way with
-- chr(8212)/chr(8211), and fold an existing hyphen region,
-- so em-dash vs hyphen can never cause a miss again.
-- Idempotent and safe to re-run. Bodies: base64 only, no $.
with folded_key(fkey, body) as (
  values
  ('introduction to ai - getting started', convert_from(decode('', 'base64'), 'utf8')),
  ('financial literacy basics - getting started', convert_from(decode('', 'base64'), 'utf8')),
  ('leadership foundations - getting started', convert_from(decode('', 'base64'), 'utf8')),
  ('communication that wins - getting started', convert_from(decode('', 'base64'), 'utf8')),
  ('build your career roadmap - getting started', convert_from(decode('', 'base64'), 'utf8')),
  ('launch a real side business in 90 days - getting started', convert_from(decode('', 'base64'), 'utf8')),
  ('find a problem worth solving', convert_from(decode('', 'base64'), 'utf8')),
  ('pick one idea and back it with evidence', convert_from(decode('', 'base64'), 'utf8')),
  ('price it without guessing', convert_from(decode('', 'base64'), 'utf8')),
  ('sell your first one', convert_from(decode('', 'base64'), 'utf8')),
  ('keep the money straight', convert_from(decode('', 'base64'), 'utf8')),
  ('make it repeatable', convert_from(decode('', 'base64'), 'utf8')),
  ('capstone - your proof', convert_from(decode('', 'base64'), 'utf8'))
)
update public.lessons l
set content = fk.body
from folded_key fk
where
  regexp_replace(regexp_replace(lower(l.title), chr(8212), '-'), chr(8211), '-') = fk.fkey;

